import sys
f=sys.argv[1]; s=open(f,encoding='utf-8').read()
def sub(a,b,n=1):
    global s; assert s.count(a)==n,(a[:90],s.count(a)); s=s.replace(a,b)
sub("'หกโมงห้าสิบห้า ผมนั่งลงข้างโทรศัพท์\\nกางหนังสือพิมพ์เก่าไว้บนตัก จะได้ดูเหมือนกำลังอ่าน'","'หกโมงห้าสิบห้า ผมนั่งข้างโทรศัพท์\\nกางหนังสือพิมพ์เก่าหน้าเดิมไว้บนตัก'")
sub("'\"ดีค่ะ\"\\nเธอเชื่อผมเสมอ นั่นแหละที่ทำให้โกหกเธอยาก'","'\"ดีค่ะ\"\\nเธอไม่ได้ถามซ้ำ ผมเลยรู้สึกว่าโกหกเธอง่ายเกินไป'")
sub("'\"ได้ยินเสียงแก้วน้ำแล้วค่ะ เก่งมาก\"\\nเธอพูดกับผมเหมือนพูดกับเด็ก ผมไม่ถือ'","'\"ได้ยินเสียงแก้วน้ำแล้วค่ะ\"\\nเธอรอจนผมวางแก้ว'")
sub("'วางหูแล้ว ผมรีบเปิดกล่องยา\\nจะได้ทำให้คำโกหกกลายเป็นความจริง ก่อนที่มันจะเย็น'","'วางหูแล้ว ผมรีบเปิดกล่องยา\\nคำโกหกคงยังแก้ทัน'")
sub("เรียกผมว่า \"คุณปู่หลี่\"\\nเธอจำชื่อผมได้']];","เรียกผมว่า \"คุณปู่หลี่\"\\nผมยกหน้าขึ้นทันที','วันนี้มีคนเรียกชื่อผมแล้ว']];")
sub("for(const [t,l] of WAIT){ await choose([{t:'รอ'}]); clock(t); await say([l]); }","for(const [t,...l] of WAIT){ await choose([{t:'รอ'}]); clock(t); await say(l); }")
sub("'สองชั่วโมงสิบนาที\\nไม่มีใครในห้องนี้รีบ และไม่มีใครอยู่คนเดียว'","'สองชั่วโมงสิบนาที\\nผมจำชื่อคนข้างๆ ได้สองคน และชื่อหมออีกหนึ่งคน'")
sub("'สามนาที\\nแต่เป็นสามนาทีที่มีคนถาม',","'สามนาที\\nผมยังไม่ทันเล่าเรื่องบันได ก็ถึงคิวคนถัดไป','ผมเคยรอข้างนอกนานกว่านี้มาก\\nแต่ไม่ได้โกรธหมอ',")
sub("'ค่ายาจ่ายเอง หนึ่งร้อยยี่สิบ\\nผมจ่ายโดยไม่ต่อ ราคาของสามนาทีนั้น ผมว่าไม่แพง'","'จ่ายเงินหนึ่งร้อยยี่สิบ\\nผมบอกขอบคุณหมอสองครั้ง ครั้งที่สองหมอเรียกชื่อคนถัดไปแล้ว'")
sub("'บางซองผมยังไม่ได้แกะ\\nผมไม่ได้เก็บยา ผมเก็บหลักฐาน ว่าปีนี้มีคนถามถึงผมกี่ครั้ง'","'บางซองยังไม่ได้แกะ\\nฉลากทุกใบมีชื่อผมอยู่','ในห้องนี้ มีของที่เขียนชื่อผมอยู่ไม่กี่อย่าง'")
sub("'วันนั้นผมโกรธ หาว่าเธอดูถูกว่าผมอ่านหนังสือไม่ออก\\nเป็นครั้งแรกที่เราทะเลาะกัน เธอร้องไห้ ผมไม่ขอโทษ','ซองนั้นผมไม่ได้ทิ้ง\\nสิบสามซองนั้น ผมเก็บเป็นหลักฐาน ซองนี้ ผมเก็บเพราะยังไม่ได้ขอโทษ'",
    "'วันนั้นผมหาว่าเธอดูถูกผม\\nเธอไม่ได้เถียง แค่เก็บปากกาลงกระเป๋า','ผมเห็นเธอร้องไห้ตอนล้างจาน\\nแต่ยังไม่ยอมขอโทษ','ซองนั้นผมไม่ได้ทิ้ง\\nสิบสามซองเป็นของหมอ ซองนี้เป็นของอาเหมย','ผมลูบรูปพระอาทิตย์ที่เธอวาด\\nสีก็ยังไม่หลุด','มีคำหนึ่งที่ผมควรพูดตั้งแต่วันนั้น'")
sub("เราอายุห่างกันสี่สิบแปดปี บางวันมันห่างกว่านั้น'","เราอายุห่างกันสี่สิบเจ็ดปี บางวันคุยกันเหมือนคนละศตวรรษ'")
sub("'สิบก้าว แล้วมันหยุด\\nหันกลับ เงยหน้าขึ้นมามองหน้าต่างชั้นสี่'","'เดินไปสิบก้าว มันหยุด\\nเงยหน้ามองหน้าต่างชั้นสี่','อาเหมยรออยู่ข้างมัน\\nรอจนมันยอมเดินต่อ'")
sub("'ผมดีใจที่มันได้เดิน\\nและผมอยากเป็นคนที่จูงมัน','สองอย่างนี้อยู่ในอกพร้อมกันได้\\nผมเพิ่งรู้วันนี้เอง'","'ผมดีใจที่มันได้เดิน\\nและคิดถึงวันที่คนถือสายจูงยังเป็นผม','ผมยกมือค้างอยู่อีกนิด\\nเผื่อมันจะหันกลับมามองอีกครั้ง'")
sub("'เกี๊ยวสิบสองลูก ผมกินหก เจ้าดำสอง\\nอีกสี่ลูกเก็บไว้ จะได้มีอะไรให้รอพรุ่งนี้'","'เกี๊ยวสิบสองลูก ผมกินหก\\nเก็บอีกหกไว้พรุ่งนี้ เจ้าดำนอนเฝ้ากล่องเปล่า'")
sub("'ก่อนนอน ผมลองยาเม็ดเหลืองหนึ่งเม็ด ตามที่หมอสั่ง'","'ก่อนนอน ผมหยิบยาเม็ดเหลืองออกมาดูฉลากอีกครั้ง\\nแล้วกินตามที่หมอสั่ง'")
sub("'ยาเช้า: ครบ'+(S.lie?'':' (มีพยาน)')","'ยาเช้า: ครบ'+(S.lie?'':' (มีพยานเป็นเสียงในโทรศัพท์)')")
sub("'อาเหมยกลับบ้าน: สองชั่วโมง เถียงกันหนึ่งเรื่อง'","'อาเหมยกลับบ้าน: สองชั่วโมง\\nเอาเกี๊ยวมาให้สิบสองลูก'")
open(f,'w',encoding='utf-8').write(s); print('d2 ok')
